#include <numeric>
#include "acl/acl.h"
#include "utils/tensor.h"
namespace Atvoss {

template <typename T>
class DeviceTensor {
public:
    DeviceTensor() = default;
    explicit DeviceTensor(Atvoss::Tensor<T>& src)
    {
        ptr_ = src.data();
    }

    T& operator[](std::size_t pos)
    {
        return ptr_[pos];
    }
    const T& operator[](std::size_t pos) const
    {
        return ptr_[pos];
    }

    void Clear()
    {
        if (ptr_ != nullptr) {
            delete[] ptr_;
            ptr_ = nullptr;
        }
    }

    auto GetPtr() const
    {
        return ptr_;
    }
    using IsTensor = void;

private:
    T* ptr_{nullptr};
};
} // namespace Atvoss

