135	    static constexpr uint32_t OUT_PARAMS_COUNT = Size_v<OutParams> * 2;
136	    static constexpr uint32_t LOCAL_VAR_COUNT = Size_v<LocalVars>;
137	
138	    static constexpr uint32_t MAX_BUFFER_COUNT = IN_PARAMS_COUNT + OUT_PARAMS_COUNT + LOCAL_VAR_COUNT;
139	    static constexpr uint32_t UB_TILE_SIZE = ArchTag::UB_SIZE / MAX_BUFFER_COUNT / 1024 * 1024;
140	    static constexpr uint64_t UB_ADDR_IN = 0;
141	    static constexpr uint64_t UB_ADDR_OUT = UB_TILE_SIZE * IN_PARAMS_COUNT;
142	    static constexpr uint64_t UB_ADDR_CALC = UB_ADDR_OUT + UB_TILE_SIZE * OUT_PARAMS_COUNT;
